const i={ui:{fig:"Fig. 1",title:"Lining · step by step",svgLabel:"An isometric drawing of how a bag is lined: the lining sewn with an opening, the outer slipped inside it, the top seam, turning the bag through the opening, closing it and topstitching.",prev:"Previous step",dot:(e,t)=>e?`Step ${e}: ${t}`:t,start:"Steps →",next:"Next →",overview:"Overview",stepOf:(e,t)=>`Step ${e} of ${t}`,machine:e=>`Machine: ${e.toLowerCase()}`,inThisStep:"In this step",takeApart:"Take it apart",putTogether:"Put it together",replay:"↻ Replay",parts:"Parts",allSteps:"Step-by-step instructions",endView:"END VIEW"},stitches:{straight:"Straight stitch"},labels:{liningInsideOut:"lining, inside out",opening8:"8 cm opening",outerRightOut:"outer, right side out",cm6:"6 cm",strapsBetween:"straps in between",rightSides:"right sides together",seam05:"0.5 cm seam",turnThrough:"turn through the opening",rightSideOut:"right side out",tuckEdges:"tuck the edges in",stitchEdge:"stitch at the very edge",pushLining:"push the lining in",pressEdge:"press the top edge",topstitch1:"1 cm topstitch"},steps:[{title:"The lined bag",text:"The outer and the lining are sewn together round the top, turned through an opening in the lining and topstitched. Tap the bag to take it apart."},{title:"Sew the lining with an opening",text:"Sew the lining like the outer and keep it inside out — but leave an 8 cm (3⅛ in) opening low in one side seam. You will turn the bag through it.",details:["Sew the lining the same way as the outer, and keep it inside out.","In one side seam, leave an opening: on the tote it is 8 cm (3⅛ in), low down, just above the bottom.","The opening can be any length, as long as the bag comes through it. A stiff item needs more room: the fabric basket, with its interfaced walls, has a 15 cm (5⅞ in) opening in a corner seam."]},{title:"Put the outer into the lining",text:"Turn the outer right side out and slip it into the inside-out lining, right sides together. The straps go in between, pinned 6 cm (2⅜ in) from the centre.",details:["Turn the outer right side out; the lining stays inside out.","On the tote, pin the straps to the top edge of the outer first: ends level with the edge, 6 cm (2⅜ in) from the centre, the loops hanging down over the bag.","Slip the outer into the lining, so the right sides face each other and the straps are caught in between. Line up the side seams and the top edges, and clip them."]},{title:"Sew round the top",text:"Sew all the way round the top, 0.5 cm (³⁄₁₆ in) from the edge, through the lining, the straps and the outer.",details:["Sew all the way round the top, 0.5 cm (³⁄₁₆ in) from the edge, through every layer: the lining, the straps and the outer.","The tote and the basket both have a 0.5 cm (³⁄₁₆ in) seam here."]},{title:"Turn it through the opening",text:"Reach into the opening in the lining and pull the whole bag out through it. The outer comes out right side out, with the lining sticking out on top.",details:["Reach into the opening in the lining, take hold of the outer and pull the whole bag out through it.","Smooth the outer out: it is now right side out. The lining is right side out too and sticks out above the bag, its opening still open."]},{title:"Close the opening",text:"Tuck the edges of the opening in along the seam line and stitch it closed on the machine, at the very edge. Or close it by hand with a ladder stitch.",details:["Tuck the raw edges of the opening inside, in line with the rest of the seam, so that the two folds meet.","The first way, on the machine: stitch the two folds together at the very edge. This is how the tote and the basket are closed; the seam then goes inside the bag, out of sight.","The second way, by hand, with a ladder stitch (also called a slip stitch): press the two folds, thread a needle with thread that matches the fabric and hide the knot inside one fold.","Take a small stitch inside one fold, then go straight across and take a small stitch inside the other one. Keep going from side to side: the threads between the folds look like the rungs of a ladder.","Every few stitches, pull the thread: the edges close and the stitches disappear. At the end, secure the thread and hide its end inside the lining."]},{title:"Push the lining in",text:"Push the lining down inside the bag and press the top edge flat with the iron.",details:["Push the lining down inside the outer, right to the bottom.","On the tote, press the top edge flat with the iron. On the basket, smooth the lining into the corners."]},{title:"Topstitch the top",text:"Topstitch all the way round the top, 1 cm (⅜ in) from the edge. On the basket the topstitch is 0.5 cm (³⁄₁₆ in) from the edge.",details:["Topstitch all the way round the top, through the outer and the lining: 1 cm (⅜ in) from the edge on the tote, 0.5 cm (³⁄₁₆ in) on the basket.","Your bag is done!"]}],legend:[{title:"Outer",text:"right side out · on the tote, the straps are sewn into its top edge, 6 cm (2⅜ in) from the centre"},{title:"Lining",text:"sewn like the outer, kept inside out, then turned and pushed inside"},{title:"Opening",text:"in a seam of the lining: 8 cm (3⅛ in) in a side seam on the tote, 15 cm (5⅞ in) in a corner seam on the basket · stitched closed at the edge"},{title:"Top seam",text:"the outer and the lining right sides together, 0.5 cm (³⁄₁₆ in) from the edge"},{title:"Topstitch",text:"1 cm (⅜ in) from the top edge on the tote, 0.5 cm (³⁄₁₆ in) on the basket"}]};export{i as default};
